import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十六章","description":"《正易心法》第十六章——卦有反对，最为关键：反体既深、对体尤妙；吉凶祸福其实一体，代谢循环特倒正之间，乾坤坎离颐大过中孚小过八卦为造化之枢机。","frontmatter":{"title":"正易心法·第十六章","description":"《正易心法》第十六章——卦有反对，最为关键：反体既深、对体尤妙；吉凶祸福其实一体，代谢循环特倒正之间，乾坤坎离颐大过中孚小过八卦为造化之枢机。","category":"guide","aliases":["正易心法第十六章","卦有反对最为关键","对体八卦"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-16.md","filePath":"yijing/zheng-yi-xin-fa/chapter-16.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-16.md"},x=p({...c,setup(u){const i=[{id:"z16-01",label:"一、反对最为关键",showLabel:!0,sentences:[["卦有",{text:"反对",glossary:"fandui"},"，最为关键。",{text:"反体",glossary:"fanti"},"既深，",{text:"对体",glossary:"duiti"},"尤妙。"]],note:["卦有反卦与对卦，这是最关键的；反体已经深妙，对体尤其奇妙。（「反」是卦画上下翻转，即综卦；「对」是每一爻阴阳全反，即错卦。**这一章是全书反对体系的枢纽**——前面讲方法论，从本章起进入卦与卦之间的关系。）"]},{id:"z16-02",label:"二、圣人密意",showLabel:!0,sentences:[["世虽知有反对之说，不能知圣人",{text:"密意",glossary:"miyi"},"在是也。"]],note:["世人虽然知道有反对之说，却不能理解圣人的深意就在这里。（世人知道的是**技术操作**（翻转、阴阳全反，人人会做）；不知道的是**圣人为什么要这样编排**——这正是本章要揭示的「密意」。）"]},{id:"z16-03",label:"三、反二对四",showLabel:!0,sentences:[["盖二卦反而为二，对而为四。既列序之，又以",{text:"杂卦",glossary:"zaguaz"},"推明义者，以为天下之吉凶祸福，贫富贵贱，其实",{text:"一体",glossary:"yiti"},"也。"]],note:["两卦互为反卦就成为两卦，再加上对卦就成为四卦一组。《周易》既用卦序排列它们，又用《杂卦传》推演阐明其义——这是为了说明：天下的吉凶祸福、贫富贵贱，其实是一个整体。（**「二卦反而为二，对而为四」是结构，「其实一体」是义理**——圣人编排这个结构，是要说这件义理。这就是「密意」。）"]},{id:"z16-04",label:"四、代谢循环未始有常",showLabel:!0,sentences:[["别而言之，其",{text:"代谢循环",glossary:"daixie"},"，特倒正之间耳，",{text:"未始有常",glossary:"weishiYouchang"},"也。"]],note:["分开来说，它们的交替更迭、循环往复，不过是倒置与正立之间的差别，从来没有固定不变的。（**吉与凶只是同一个卦的「倒正之间」**：泰卦翻转是否卦，否卦翻转是泰卦——吉凶不是两样东西，是同一件事的两个朝向。这是《周易》「无常」观最精确的表达：不是悲观，不是乐观，而是「未始有常」。）"]},{id:"z16-05",label:"五、对体八卦",showLabel:!0,sentences:[["然反对则诸卦皆是，对体则乾、坤、坎、离、颐、大过、中孚、小过而已。"]],note:["然而反卦与对卦，六十四卦都有；但对体（翻转后卦体不变的卦），只有乾、坤、坎、离、颐、大过、中孚、小过这八卦。（这八卦的特点是**翻转 180 度后仍是自身**——乾䷀、坤䷁、坎䷜、离䷝（上下卦相同），颐䷚、大过䷛、中孚䷼、小过䷽（爻序为回文，正读反读一样）。）"]},{id:"z16-06",label:"六、造化之枢机",showLabel:!0,sentences:[["此八卦与诸卦不同，在《易》道，乃",{text:"死生寿夭",glossary:"sishengShouyao"},"造化之",{text:"枢机",glossary:"shuji"},"也。其体不变，故曰：对体尤妙。"]],note:["这八卦与其他卦不同，在《易》道中，是死生寿夭、造化的枢机所在。它们的卦体翻转后不变，所以说「对体尤妙」。（**枢机＝门轴**：普通卦有正有反，在转化中存在，是门扇；对体卦翻转后仍是自身，是门轴。**宇宙万物在吉凶祸福中循环转化（门扇开关），但必须有不变的枢轴支撑这个转化（门轴）。** 这八卦就是宇宙转化的不变支点。）"]}],o=[{id:"fandui",term:"反对",pinyin:"fǎn duì",meaning:"反卦（上下翻转，即综卦）与对卦（阴阳全反，即错卦）。"},{id:"fanti",term:"反体",pinyin:"fǎn tǐ",meaning:"翻转后的卦体。将卦画倒过来读，得到另一卦。"},{id:"duiti",term:"对体",pinyin:"duì tǐ",meaning:"阴阳全反的卦体。每一爻阴变阳、阳变阴，得到对卦。"},{id:"miyi",term:"密意",pinyin:"mì yì",meaning:"隐秘的深意。圣人编排《周易》卦序的深层用意。"},{id:"zaguaz",term:"杂卦",pinyin:"zá guà",meaning:"《杂卦传》，十翼之一，以对比方式说明卦义。"},{id:"yiti",term:"一体",pinyin:"yī tǐ",meaning:"同一个整体。吉凶祸福本是一体，非截然对立。"},{id:"daixie",term:"代谢循环",pinyin:"dài xiè xún huán",meaning:"交替更迭，循环往复。吉凶祸福的相互转化。"},{id:"weishiYouchang",term:"未始有常",pinyin:"wèi shǐ yǒu cháng",meaning:"从来没有固定不变的。吉凶无常，随时转化。"},{id:"sishengShouyao",term:"死生寿夭",pinyin:"sǐ shēng shòu yāo",meaning:"生死与长寿夭折。生命的根本问题。"},{id:"shuji",term:"枢机",pinyin:"shū jī",meaning:"门轴，转动的关键点。对体八卦是宇宙转化的不变支点。"}];return(b,a)=>{const l=s("DaoTextReading"),r=s("DaoKeywordCards");return d(),g("div",null,[a[0]||(a[0]=t("",23)),e(l,{colophon:"反对关键 · 吉凶一体 · 代谢循环 · 对体尤妙",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十六章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"反体 · 对体",pinyin:["fǎn","duì"],meaning:"反体＝卦画上下翻转（综卦）；对体＝每一爻阴阳全反（错卦）。前者说「二卦反而为二」，后者说「对而为四」。"},{term:"圣人密意",pinyin:["mì","yì"],meaning:"世人知道「反对」的技术操作，不知道圣人为何这样编排——密意即「吉凶祸福其实一体」。"},{term:"其实一体",pinyin:["qí","shí"],meaning:"吉凶祸福、贫富贵贱本是一个整体。吉与凶只是同一卦的「倒正之间」，非两样东西。"},{term:"未始有常",pinyin:["wèi","shǐ"],meaning:"从来没有固定不变的。不是悲观也不是乐观，而是「吉凶本一体、转化在倒正之间」。"},{term:"对体八卦",pinyin:["duì","tǐ"],meaning:"乾坤坎离（上下卦相同）＋颐大过中孚小过（爻序为回文）——翻转 180 度后仍是自身，是六十四卦中唯一「没有另一个对立面」的卦。"},{term:"造化之枢机",pinyin:["shū","jī"],meaning:"枢机即门轴。普通卦是门扇（有正有反），对体卦是门轴（体不变）——宇宙转化的不变支点。"}]}),a[3]||(a[3]=t("",28))])}}});export{y as __pageData,x as default};
